//! Termigator desktop application: QObjects for QML and startup.
//!
//! A library rather than code in `main.rs` because the C++ half generated by cxx-qt-build is
//! linked into every target of this package (binaries, integration tests); the Rust half it
//! calls must therefore live in the library they all link.
//!
//! UI layout: `qml/<area>/*.qml` + `src/<area>_qobj.rs`. The shell is
//! `qml/shell/ShellWindow.qml` with `AppController` (`shell_qobj.rs`); the host list is
//! `qml/sidebar/HostsPanel.qml` with `HostListModel` (`sidebar_qobj.rs`).

mod editors_qobj;
mod files_helper_qobj;
mod files_qobj;
mod files_sync_qobj;
mod import_qobj;
mod job_windows;
mod panes_qobj;
