use std::ffi::OsString;
use std::process::ExitCode;

use cxx_qt_lib::{QGuiApplication, QQmlApplicationEngine, QQuickStyle, QString, QUrl};
use cxx_qt_lib_extras::QApplication;
use termigator_core::paths::ProcessEnv;
use termigator_core::proto::askpass;
use termigator_core::single_instance::{send_command, split_remote_args};

pub use shell_qobj::SMOKE_TEST_ENV;

const MAIN_QML: &str = "qrc:/qt/qml/Termigator/qml/shell/ShellWindow.qml";

/// The `SSH_ASKPASS` helper: asks the running Termigator for the answer to ssh's prompt
/// (`argv[1]`) and prints it. Exit 1 = refused or no Termigator to ask; ssh then fails the login.
fn askpass_helper(channel: &str) -> ExitCode {
    use std::io::Write;
    let prompt = std::env::args().nth(1).unwrap_or_default();
    let token = std::env::var(askpass::TOKEN_ENV).unwrap_or_default();
    match askpass::fetch(std::path::Path::new(channel), &token, &prompt) {
        Ok(Some(reply)) => {
            let mut out = std::io::stdout();
            if out.write_all(&reply).and_then(|()| out.flush()).is_ok() {
                return ExitCode::SUCCESS;
            }
            ExitCode::FAILURE
        }
        _ => ExitCode::FAILURE,
    }
}

/// `--version` / `--help` (also `-V` / `-h`): the text to print instead of starting the app.
fn info_text<I: IntoIterator<Item = OsString>>(args: I) -> Option<String> {
    let version = format!("termigator {}", env!("CARGO_PKG_VERSION"));
    args.into_iter().find_map(|a| match a.to_str() {
        Some("--version" | "-V") => Some(version.clone()),
        Some("--help" | "-h") => Some(format!(
            "{version}\nSSH / RDP / VNC / telnet / serial launcher with an embedded terminal.\n\n\
             Usage: termigator [--toggle | --show]\n\n  \
             --toggle       show or hide the running window (bind it to a global shortcut)\n  \
             --show         bring the running window to the front\n  \
             -V, --version  print the version\n  \
             -h, --help     print this help\n\n\
             Config: {} (override with TERMIGATOR_CONFIG_DIR).",
            termigator_core::paths::Paths::resolve(
                termigator_core::paths::Layout::ACTIVE,
                &ProcessEnv,
                std::path::Path::new("/"),
            )
            .config_dir
            .display()
        )),
        _ => None,
    })
}

/// Entry point: `--toggle` / `--show` reach a running Termigator before any Qt exists;
/// otherwise loads the config, creates the application and runs the main window.
pub fn run() -> ExitCode {
    // ssh started us as its SSH_ASKPASS helper: answer one prompt, no Qt.
    let channel = std::env::var("TERMIGATOR_ASKPASS_CHANNEL").ok();
    if askpass::is_helper_invocation(channel.as_deref()) {
        return askpass_helper(channel.as_deref().unwrap_or_default());
    }
    if let Some(text) = info_text(std::env::args_os().skip(1)) {
        println!("{text}");
        return ExitCode::SUCCESS;
    }
    // TERMIGATOR_STARTUP_TRACE=1 prints phase times and RSS (startup benchmarks).
    let trace_start = std::time::Instant::now();
    let trace = |label: &str| {
        if std::env::var_os("TERMIGATOR_STARTUP_TRACE").is_some() {
            let rss = std::fs::read_to_string("/proc/self/status")
                .ok()
                .and_then(|s| {
                    s.lines().find_map(|l| {
                        l.strip_prefix("VmRSS:")?
                            .trim()
                            .strip_suffix(" kB")?
                            .trim()
                            .parse::<f64>()
                            .ok()
                    })
                })
                .map_or(f64::NAN, |kb| kb / 1024.0);
            eprintln!(
                "STARTUP {:>6.1} ms rss {:>6.1} MB  {label}",
                trace_start.elapsed().as_secs_f64() * 1000.0,
                rss
            );
        }
    };
    trace("process start");
    // `--warm-up` (the Windows installer, at the end of the install): start once without a window
    // and quit at the first frame, so the first real start finds the antivirus scan of the DLLs and
    // Qt's QML cache already done. Its own throw-away config folder leaves the user's alone.
    let warm_up = std::env::args_os()
        .skip(1)
        .any(|a| a == "--warm-up")
        .then(|| std::env::temp_dir().join(format!("termigator-warm-up-{}", std::process::id())));
    if let Some(dir) = &warm_up {
        // SAFETY: nothing else runs yet (no thread started, Qt not created), so no one reads the
        // environment while it changes.
        unsafe {
            std::env::set_var("QT_QPA_PLATFORM", "offscreen");
            std::env::set_var("TERMIGATOR_CONFIG_DIR", dir);
            std::env::set_var(SMOKE_TEST_ENV, dir.join("warm-up.png"));
        }
    }
    let (remote, _rest) = split_remote_args(std::env::args_os().skip(1));
    if let Some(command) = remote {
        let token = std::env::var("XDG_ACTIVATION_TOKEN").unwrap_or_default();
        if send_command(&ProcessEnv, command.as_str(), &token).unwrap_or(false) {
            return ExitCode::SUCCESS;
        }
        // None running: this process becomes the window.
    }
    trace("args split");
    job_windows::install();
    let startup = match shell_qobj::AppState::load() {
        Ok(s) => s,
        Err(e) => {
            eprintln!("Error loading config: {e}");
            // Started from the menu there is no terminal: say it in a window. Not
            // offscreen (tests, the installer's warm-up), where nobody could close it, nor without
            // a display (ssh, cron), where Qt would abort with a core dump.
            let set = |k: &str| std::env::var_os(k).is_some_and(|v| !v.is_empty());
            let no_display = cfg!(target_os = "linux")
                && !set("DISPLAY")
                && !set("WAYLAND_DISPLAY")
                && !set("QT_QPA_PLATFORM");
            let headless = std::env::var_os("QT_QPA_PLATFORM").is_some_and(|p| p == "offscreen")
                || set(SMOKE_TEST_ENV)
                || no_display;
            if !headless {
                let _app = QApplication::new();
                let dir = shell_qobj::app_paths().config_dir;
                shell_qobj::qobject::startup_error(
                    &QString::from(e.to_string().as_str()),
                    &QString::from(dir.to_string_lossy().as_ref()),
                );
            }
            return ExitCode::FAILURE;
        }
    };

    trace("config loaded");
    // QApplication, not QGuiApplication: qqc2-desktop-style paints through QStyle and
    // Qt.labs.platform falls back to QMenu / QSystemTrayIcon only when widgets are available.
    let mut app = QApplication::new();
    let Some(mut app_ref) = app.as_mut() else {
        return ExitCode::FAILURE;
    };
    trace("QApplication created");
    app_ref
        .as_mut()
        .set_application_name(&QString::from("Termigator"));
    // Wayland matches the surface app_id to "<name>.desktop" for the window / taskbar icon.
    QGuiApplication::set_desktop_file_name(&QString::from("termigator"));
    shell_qobj::qobject::apply_fixed_look(&QString::from(
        preferences_qobj::configured_ui_theme(&startup.cfg).as_str(),
    ));
    // Same rule as KDE applications: an explicit user choice of style wins.
    if std::env::var_os("QT_QUICK_CONTROLS_STYLE").is_none() {
        let available: Vec<String> = preferences_qobj::qobject::available_quick_styles()
            .iter()
            .map(|s| s.to_string())
            .collect();
        let style = preferences_qobj::startup_style(&startup.cfg, &available);
        QQuickStyle::set_style(&QString::from(style.as_str()));
    }
    trace("style chosen");
    // The terminal types (`Termigator.Terminal`) and the router that delivers the bridge's pty
    // events to the tabs. Konsole's colour scheme directories are scanned by `termigator-core`.
    shell_qobj::hand_over(startup);
    termigator_term_bridge::register_ghostty_types();
    // A see-through terminal background (Preferences → Terminal) needs windows with alpha; set
    // before the first window so the setting can change without a restart.
    termigator_term_bridge::enable_alpha_windows();
    trace("controller handed over + terminal types registered");
    terminal_qobj::install_router();
    if std::env::var_os(SMOKE_TEST_ENV).is_some_and(|v| v != OsString::new()) {
        // Synthetic key presses for qml/shell/SmokeCheck.qml; never in a normal run.
        termigator_term_bridge::register_probe_types();
    }

    trace("router");
    let mut engine = QQmlApplicationEngine::new();
    let Some(mut engine_ref) = engine.as_mut() else {
        eprintln!("termigator: cannot create the QML engine");
        return ExitCode::FAILURE;
    };
    engine_ref
        .as_mut()
        .on_object_creation_failed(|_, url| {
            eprintln!("termigator: cannot load {url}");
            std::process::exit(1);
        })
        .release();
    trace("QML engine created");
    engine_ref.load(&QUrl::from(MAIN_QML));
    trace("QML loaded (ShellWindow + panels)");

    let code = app_ref.exec();
    // The QML objects own the control socket and its lock: gone before the new process asks.
    drop(engine);
    termigator_core::proto::ssh::remove_private_key_copies();
    if shell_qobj::RESTART.load(std::sync::atomic::Ordering::SeqCst) {
        restart();
    }
    if let Some(dir) = warm_up {
        let _ = std::fs::remove_dir_all(dir);
    }
    ExitCode::from(u8::try_from(code).unwrap_or(1))
}

/// `requestRestart`: the same program and arguments again, told to reopen the saved tabs.
fn restart() {
    let (_, args) = split_remote_args(std::env::args_os().skip(1));
    let args = args
        .into_iter()
        .filter(|a| a != shell_qobj::RESTORE_ARG && a != "--warm-up");
    let started = std::env::current_exe().and_then(|exe| {
        std::process::Command::new(exe)
            .args(args)
            .arg(shell_qobj::RESTORE_ARG)
            .spawn()
    });
    if let Err(e) = started {
        eprintln!("termigator: cannot restart: {e}");
    }
}

#[cfg(test)]
mod tests {
    use super::info_text;
    use std::ffi::OsString;

    fn args(list: &[&str]) -> Vec<OsString> {
        list.iter().map(OsString::from).collect()
    }

    #[test]
    fn version_and_help_flags_print_instead_of_starting() {
        let v = format!("termigator {}", env!("CARGO_PKG_VERSION"));
        assert_eq!(info_text(args(&["--version"])).as_deref(), Some(v.as_str()));
        assert_eq!(info_text(args(&["-V"])).as_deref(), Some(v.as_str()));
        let help = info_text(args(&["--help"])).expect("help");
        assert!(help.starts_with(&v) && help.contains("--toggle") && help.contains("--show"));
        assert!(info_text(args(&["-h"])).is_some());
        assert_eq!(info_text(args(&[])), None);
        assert_eq!(info_text(args(&["--toggle"])), None);
        assert_eq!(
            info_text(args(&["--smoke-check=shell/LookCheck.qml"])),
            None
        );
    }
}
